insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_science_v1'
from (values
('112.26.b.6.A',2,'Which state of matter has a definite shape and a definite volume?','["solid", "plasma only", "gas", "liquid"]'::jsonb,0,'Particles in a solid are locked in place, so it keeps both its shape and its volume.','original'),
('112.26.b.6.A',3,'A sealed balloon is squeezed into a smaller space and the gas inside takes up less volume. Why can the gas be compressed so easily?','["its particles have no energy", "its particles are far apart", "its particles are locked together", "its particles are heavier than a solid''s"]'::jsonb,1,'Gas particles have lots of empty space between them.','original'),
('112.26.b.6.A',3,'Water is poured from a tall glass into a wide bowl. What happens to its shape and volume?','["neither changes", "both change", "shape changes, volume stays the same", "shape stays the same, volume changes"]'::jsonb,2,'A liquid takes the shape of its container but keeps its volume.','original'),
('112.26.b.6.A',3,'Compared with the particles in ice, the particles in water vapor have...','["less kinetic energy", "the same kinetic energy", "no kinetic energy", "more kinetic energy"]'::jsonb,3,'Gas particles move fastest, so they have the most kinetic energy.','original'),
('112.26.b.6.A',3,'Which statement describes the particles in a liquid?','["they stay close together but slide past each other", "they are fixed in rigid positions", "they are far apart and move freely", "they do not move at all"]'::jsonb,0,'Liquid particles are close but can flow.','original'),
('112.26.b.6.A',4,'A solid is heated until it melts. What happens to the motion of its particles as the thermal energy increases?','["they move slower and pack tighter", "they move faster and break free of fixed positions", "they disappear", "they stop moving"]'::jsonb,1,'Added energy speeds particles up so they can slide past each other.','original'),
('112.26.b.6.A',4,'A student sees that a gas always fills its whole container, while a liquid does not. What explains the difference?','["gas particles are larger than liquid particles", "gas particles are attracted strongly to each other", "gas particles spread out because they move freely with little attraction", "liquids have more kinetic energy"]'::jsonb,2,'Weak attractions let gas particles spread out to fill any space.','original'),
('112.26.b.6.B',2,'Which of these is a pure substance?','["soil", "salt water", "trail mix", "distilled water"]'::jsonb,3,'A pure substance has just one kind of matter; distilled water is only H2O.','original'),
('112.26.b.6.B',3,'Sugar is stirred into water until it can no longer be seen. This kind of mixture is called a...','["solution", "compound", "heterogeneous mixture", "pure substance"]'::jsonb,0,'A homogeneous mixture (solution) looks the same throughout.','original'),
('112.26.b.6.B',3,'A bowl of cereal with milk has separate pieces you can see. Which kind of matter is it?','["element", "heterogeneous mixture", "homogeneous mixture", "pure substance"]'::jsonb,1,'The parts are not evenly mixed and can be seen.','original'),
('112.26.b.6.B',3,'Which is a homogeneous mixture?','["a pizza", "a salad", "air", "gravel and sand"]'::jsonb,2,'Air looks uniform throughout, with gases evenly mixed.','original'),
('112.26.b.6.B',4,'Iron filings and sand are mixed together. Which method separates them using a physical property?','["adding more sand", "boiling the mixture", "burning the mixture", "using a magnet"]'::jsonb,3,'Iron is magnetic and sand is not.','original'),
('112.26.b.6.B',3,'Which is a way to separate saltwater into salt and water?','["evaporating the water", "adding more salt", "using a ruler", "using a magnet"]'::jsonb,0,'Heating drives off the water and leaves the salt behind.','original'),
('112.26.b.6.B',4,'Gold melts at a specific temperature, and the melted gold has the same properties as the solid. This suggests gold is a...','["heterogeneous mixture", "pure substance", "solution of several metals", "mixture"]'::jsonb,1,'Pure substances have fixed, consistent properties.','original'),
('112.26.b.6.C',2,'Most elements on the periodic table are...','["gases", "nonmetals", "metals", "metalloids"]'::jsonb,2,'The majority of elements are metals.','original'),
('112.26.b.6.C',3,'A shiny element that is easily shaped and conducts electricity well is most likely a...','["nonmetal", "gas", "noble gas", "metal"]'::jsonb,3,'Luster, malleability and conductivity are metal properties.','original'),
('112.26.b.6.C',3,'An element is brittle when solid, dull, and a poor conductor of heat. It is most likely a...','["nonmetal", "rare Earth element", "metal", "metalloid"]'::jsonb,0,'Brittle, dull and poor conductivity describe nonmetals.','original'),
('112.26.b.6.C',3,'Silicon has properties between those of metals and nonmetals. It is classified as a...','["metal", "metalloid", "nonmetal", "halogen only"]'::jsonb,1,'Metalloids have mixed properties.','original'),
('112.26.b.6.C',4,'Silicon is used in computer chips because it can conduct electricity under some conditions but not others. This is a property of a...','["noble gas", "halogen", "metalloid", "alkali metal"]'::jsonb,2,'Metalloids are semiconductors.','original'),
('112.26.b.6.C',3,'Rare Earth elements are important in modern life because they are used in...','["plain glass jars", "paper and cardboard", "bread and pasta", "magnets and electronics such as phones"]'::jsonb,3,'Rare Earth elements are used in strong magnets, screens and batteries.','original'),
('112.26.b.6.C',3,'Copper is used for electrical wires because it is...','["a good conductor of electricity", "very brittle", "a nonmetal", "a poor conductor of electricity"]'::jsonb,0,'Copper is a metal that conducts electricity well.','original'),
('112.26.b.6.D',3,'A block of wood floats on water, but a rock of the same size sinks. Which has the greater density?','["they are equal", "the rock", "neither", "the wood"]'::jsonb,1,'Objects denser than the fluid sink; less dense objects float.','original'),
('112.26.b.6.D',3,'An object has a mass of 20 g and a volume of 10 cm³. What is its density?','["30 g/cm³", "0.5 g/cm³", "2 g/cm³", "10 g/cm³"]'::jsonb,2,'Density = mass ÷ volume = 20 ÷ 10.','original'),
('112.26.b.6.D',4,'Oil floats on top of water. What does this show?','["oil has more mass in each cm³", "water is lighter than oil", "oil is heavier than water", "oil is less dense than water"]'::jsonb,3,'Less dense liquids float on denser ones.','original'),
('112.26.b.6.D',4,'A liquid has a density of 1.5 g/mL. A ball with a density of 1.2 g/mL is placed in it. What happens?','["the ball floats", "the ball sinks", "the ball dissolves", "the ball stays at the bottom"]'::jsonb,0,'The ball is less dense than the liquid.','original'),
('112.26.b.6.D',4,'A student has 50 g of lead and 50 g of foam. The foam takes up much more space. What does this show?','["lead has less mass", "foam is less dense than lead", "they have equal density", "foam is denser than lead"]'::jsonb,1,'The same mass in a larger volume means lower density.','original'),
('112.26.b.6.D',3,'A steel ship floats even though steel is denser than water. Why?','["steel gets lighter in water", "water is denser than air", "the ship''s overall shape holds air, lowering its average density", "the ship has no mass"]'::jsonb,2,'The ship''s hollow shape makes its overall density less than water.','original'),
('112.26.b.6.D',4,'Three floating objects have densities of 0.2 g/cm³, 0.6 g/cm³ and 0.9 g/cm³. Which one floats highest in water?','["all float at the same height", "the 0.9 g/cm³ object", "the 0.6 g/cm³ object", "the 0.2 g/cm³ object"]'::jsonb,3,'The least dense object floats highest.','original'),
('112.26.b.6.E',2,'Which is evidence of a chemical change?','["bubbles of gas forming when two substances mix", "sugar dissolving", "ice melting", "paper being cut"]'::jsonb,0,'A new gas forming is a sign of a new substance.','original'),
('112.26.b.6.E',3,'A match burns and gives off heat and light. What type of change is this?','["physical change", "chemical change", "no change", "state change only"]'::jsonb,1,'Burning forms new substances and releases energy.','original'),
('112.26.b.6.E',3,'Mixing baking soda and vinegar makes fizzing bubbles. What does this show?','["a mixture was separated", "the vinegar evaporated", "a new substance, a gas, was formed", "a solid was cut"]'::jsonb,2,'Gas production is evidence of a chemical change.','original'),
('112.26.b.6.E',3,'A cut apple turns brown. This is most likely a...','["change of state", "change in shape only", "physical change", "chemical change"]'::jsonb,3,'A color change from reacting with oxygen forms a new substance.','original'),
('112.26.b.6.E',4,'Which is a physical change rather than a chemical change?','["chopping wood into small pieces", "a banana ripening", "iron rusting", "wood burning in a fire"]'::jsonb,0,'Chopping changes size, not the type of substance.','original'),
('112.26.b.6.E',4,'Two clear liquids are mixed and a solid forms in the cup. What is the solid called?','["an element", "a precipitate", "a solution", "a mixture"]'::jsonb,1,'A solid formed from liquids in a chemical reaction is a precipitate.','original'),
('112.26.b.6.E',4,'A cold pack gets cold when its chemicals are mixed. Which evidence of chemical change is this?','["a change in volume of the pack", "a change in shape", "a change in thermal energy", "a change in size"]'::jsonb,2,'Absorbing or releasing heat can show a chemical change.','original'),
('112.26.b.7.A',2,'What force pulls objects toward Earth?','["tension", "magnetism", "friction", "gravity"]'::jsonb,3,'Gravity is the force of attraction toward Earth''s center.','original'),
('112.26.b.7.A',3,'A book slides across a table and slows to a stop. Which force slows it down?','["friction", "an applied force", "gravity", "magnetism"]'::jsonb,0,'Friction opposes motion between surfaces.','original'),
('112.26.b.7.A',3,'A book rests on a table. Which force from the table pushes up on the book?','["applied force", "normal force", "magnetic force", "friction"]'::jsonb,1,'The normal force is perpendicular to the surface and supports the object.','original'),
('112.26.b.7.A',3,'A student pushes a shopping cart across the floor. The push is an example of a(n)...','["normal force", "gravitational force", "applied force", "frictional force"]'::jsonb,2,'An applied force comes from a person or object acting on something.','original'),
('112.26.b.7.A',3,'A refrigerator magnet sticks to a metal door. Which force holds it there?','["normal force only", "friction only", "gravity only", "magnetic force"]'::jsonb,3,'Magnetic attraction pulls the magnet to the iron door.','original'),
('112.26.b.7.A',4,'Why does a skater glide farther on smooth ice than on a rough sidewalk?','["there is less friction on ice", "there is more gravity on ice", "ice has more mass", "the skater is lighter on ice"]'::jsonb,0,'Smoother surfaces create less friction.','original'),
('112.26.b.7.A',4,'Which action increases friction between a bike tire and the road?','["riding on ice", "riding on a rougher surface", "adding oil to the road", "letting the tires wear completely smooth"]'::jsonb,1,'Rough surfaces increase friction.','original'),
('112.26.b.7.B',3,'Two students push on a box in opposite directions, each with 20 N. What is the net force?','["40 N", "10 N", "0 N", "20 N"]'::jsonb,2,'Equal opposite forces cancel, so the forces are balanced.','original'),
('112.26.b.7.B',3,'A box is pushed right with 30 N and left with 10 N. What is the net force?','["40 N to the right", "20 N to the left", "30 N to the left", "20 N to the right"]'::jsonb,3,'30 − 10 = 20, in the direction of the bigger force.','original'),
('112.26.b.7.B',3,'When forces on an object are balanced, the object...','["stays at rest or keeps moving at constant velocity", "speeds up", "always stops", "moves in a circle"]'::jsonb,0,'Balanced forces do not change motion.','original'),
('112.26.b.7.B',4,'A rope is pulled left with 50 N and right with 35 N. What is the net force and what will happen?','["15 N right; the rope accelerates right", "15 N left; the rope accelerates left", "85 N left; the rope stays still", "0 N; the rope stays still"]'::jsonb,1,'Unbalanced forces cause acceleration toward the bigger force.','original'),
('112.26.b.7.B',4,'A book on a table has a 10 N weight pulling down and the table pushes up with 10 N. The forces are...','["zero", "friction", "balanced", "unbalanced"]'::jsonb,2,'Equal and opposite forces are balanced, so the book stays at rest.','original'),
('112.26.b.7.B',4,'A cart is pushed forward with 25 N and friction pushes back with 5 N. What is the net force?','["5 N forward", "20 N backward", "30 N forward", "20 N forward"]'::jsonb,3,'25 − 5 = 20 in the forward direction.','original'),
('112.26.b.7.B',4,'Which diagram shows unbalanced forces? An arrow of 8 N right and an arrow of 3 N left. The net force is...','["5 N to the right", "11 N to the right", "0 N", "5 N to the left"]'::jsonb,0,'8 − 3 = 5 toward the larger force.','original'),
('112.26.b.7.C',2,'According to Newton''s Third Law, forces always come in...','["groups of four", "pairs", "threes", "singles"]'::jsonb,1,'For every action there is an equal and opposite reaction.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_science_v1'
from (values
('112.26.b.7.C',3,'A swimmer pushes backward on the water. What pushes the swimmer forward?','["gravity", "friction with the air only", "the water pushes back on the swimmer", "nothing"]'::jsonb,2,'The reaction force from the water is equal and opposite.','original'),
('112.26.b.7.C',3,'When a rocket expels gas downward, the rocket moves upward. This is an example of...','["Newton''s First Law only", "conservation of mass", "friction", "Newton''s Third Law"]'::jsonb,3,'The gas is pushed down, so the rocket is pushed up.','original'),
('112.26.b.7.C',3,'A person pushes on a wall with 30 N of force. How much force does the wall push back with?','["30 N", "0 N", "15 N", "60 N"]'::jsonb,0,'Action and reaction forces are equal in size.','original'),
('112.26.b.7.C',4,'A bat hits a ball. The bat exerts a force on the ball. What also happens?','["the ball exerts a larger force", "the ball exerts an equal and opposite force on the bat", "the bat feels no force", "the ball exerts no force"]'::jsonb,1,'Force pairs act on different objects.','original'),
('112.26.b.7.C',4,'A person jumps off a small boat and the boat moves backward. Why?','["the water pushes the boat only", "the boat is lighter than the water", "the person pushes the boat backward as the boat pushes the person forward", "gravity pulls the boat"]'::jsonb,2,'The two objects push on each other with equal and opposite forces.','original'),
('112.26.b.7.C',4,'Why do the action and reaction forces not cancel each other?','["one of them is not a real force", "they are unequal", "they act in the same direction", "they act on different objects"]'::jsonb,3,'Cancelling needs forces on the same object.','original'),
('112.26.b.8.A',2,'A ball held high above the ground has which type of energy?','["gravitational potential energy", "sound energy", "chemical energy", "elastic potential energy"]'::jsonb,0,'Height gives an object stored energy due to gravity.','original'),
('112.26.b.8.A',3,'A stretched rubber band has which type of energy?','["gravitational potential energy", "elastic potential energy", "kinetic energy", "nuclear energy"]'::jsonb,1,'Stretching stores energy in the band.','original'),
('112.26.b.8.A',3,'The energy stored in food and fuel is called...','["elastic potential energy", "kinetic energy", "chemical potential energy", "thermal energy"]'::jsonb,2,'Chemical bonds store energy.','original'),
('112.26.b.8.A',3,'A moving skateboard has...','["only chemical energy", "no energy", "only potential energy", "kinetic energy"]'::jsonb,3,'Kinetic energy is the energy of motion.','original'),
('112.26.b.8.A',4,'A roller coaster car is at the top of a hill. As it rolls down, its potential energy...','["decreases while its kinetic energy increases", "increases while its kinetic energy decreases", "disappears completely", "stays the same"]'::jsonb,0,'Stored energy changes into motion as it falls.','original'),
('112.26.b.8.A',4,'Which has the most kinetic energy: a 2 kg ball moving at 5 m/s or a 2 kg ball moving at 10 m/s?','["neither has kinetic energy", "the ball moving at 10 m/s", "they have equal kinetic energy", "the ball moving at 5 m/s"]'::jsonb,1,'Faster objects have more kinetic energy.','original'),
('112.26.b.8.A',4,'A compressed spring is released and a toy shoots forward. Which energy change occurred?','["kinetic to gravitational", "thermal to elastic", "elastic potential to kinetic", "chemical to nuclear"]'::jsonb,2,'Stored spring energy became motion.','original'),
('112.26.b.8.B',3,'The law of conservation of energy says that energy...','["disappears when used", "is always created in machines", "is destroyed by friction", "cannot be created or destroyed, only transformed"]'::jsonb,3,'Total energy stays constant.','original'),
('112.26.b.8.B',3,'In photosynthesis, plants transform light energy into...','["chemical energy", "sound energy", "elastic energy", "nuclear energy"]'::jsonb,0,'Plants store the energy in sugar molecules.','original'),
('112.26.b.8.B',3,'In an electrical circuit with a light bulb, electrical energy is transformed mostly into...','["sound and elastic energy", "light and thermal energy", "nuclear energy", "chemical energy"]'::jsonb,1,'The bulb glows and gets warm.','original'),
('112.26.b.8.B',4,'In a food web, a rabbit eats grass and a fox eats the rabbit. Energy from the Sun ends up where?','["gone after the grass is eaten", "created by the rabbit", "stored in the grass, then passed to the rabbit and fox", "destroyed in the fox"]'::jsonb,2,'Energy flows through the web by eating.','original'),
('112.26.b.8.B',4,'A roller coaster never reaches a hill as high as the first one. Where does some of the energy go?','["it is created again at the top", "it becomes potential energy only", "it is destroyed", "it is transformed into thermal energy by friction"]'::jsonb,3,'Friction changes some mechanical energy into heat.','original'),
('112.26.b.8.B',4,'A battery-powered toy car moves. Which energy transformation occurs?','["chemical to electrical to kinetic", "nuclear to elastic", "kinetic to chemical", "sound to thermal"]'::jsonb,0,'The battery''s chemical energy powers a motor.','original'),
('112.26.b.8.B',4,'A pendulum swings back and forth and eventually stops. Why?','["energy is destroyed", "its mechanical energy is gradually transferred to thermal energy by air resistance and friction", "gravity turns off", "the pendulum becomes lighter"]'::jsonb,1,'No energy is lost; it is transferred to the surroundings.','original'),
('112.26.b.8.C',2,'In a transverse wave, the particles of the medium move...','["in the same direction as the wave", "not at all", "at right angles to the direction the wave travels", "parallel to the wave direction"]'::jsonb,2,'Like a rope wave moving up and down while traveling across.','original'),
('112.26.b.8.C',3,'In a longitudinal wave, the particles move...','["in circles", "up and down", "at right angles to the wave", "back and forth parallel to the direction the wave travels"]'::jsonb,3,'Compressions and expansions travel along the same line.','original'),
('112.26.b.8.C',3,'Sound waves are an example of which kind of wave?','["longitudinal", "electromagnetic", "surface only", "transverse"]'::jsonb,0,'Sound is made of compressions and rarefactions.','original'),
('112.26.b.8.C',3,'Waves transfer...','["matter without energy", "energy without moving matter along with them", "neither", "both matter and energy permanently"]'::jsonb,1,'A wave carries energy; the medium only vibrates.','original'),
('112.26.b.8.C',4,'A water wave moves a floating cork. What does the cork mainly do?','["travel with the wave to shore", "move opposite to the wave", "bob up and down in place", "sink at once"]'::jsonb,2,'The medium moves in place while energy moves on.','original'),
('112.26.b.8.C',4,'The highest point of a transverse wave is called the...','["rarefaction", "trough", "compression", "crest"]'::jsonb,3,'The crest is the top of the wave.','original'),
('112.26.b.8.C',4,'The distance between two crests of a transverse wave is the...','["wavelength", "amplitude", "period", "frequency"]'::jsonb,0,'Wavelength is the crest-to-crest distance.','original'),
('112.26.b.9.A',2,'What causes the seasons on Earth?','["Earth''s distance from the Sun changing a lot", "the tilt of Earth''s axis as it revolves around the Sun", "the Sun getting bigger and smaller", "the Moon''s phases"]'::jsonb,1,'Tilt changes how directly sunlight hits each hemisphere.','original'),
('112.26.b.9.A',3,'When the Northern Hemisphere is tilted toward the Sun, it is...','["spring in the Southern Hemisphere", "night all day", "summer in the Northern Hemisphere", "winter in the Northern Hemisphere"]'::jsonb,2,'Direct sunlight and longer days bring summer.','original'),
('112.26.b.9.A',3,'It is winter in Texas. What season is it in Australia?','["fall", "winter", "spring", "summer"]'::jsonb,3,'Hemispheres have opposite seasons.','original'),
('112.26.b.9.A',3,'About how long does it take Earth to revolve once around the Sun?','["one year", "one week", "one month", "one day"]'::jsonb,0,'A revolution takes about 365 days.','original'),
('112.26.b.9.A',4,'If Earth''s axis were not tilted, what would happen to the seasons?','["seasons would be more extreme", "there would be little or no seasonal change", "it would always be winter", "day would last forever"]'::jsonb,1,'Tilt causes seasons.','original'),
('112.26.b.9.A',4,'On the summer solstice in the Northern Hemisphere, the Sun''s rays are...','["least direct and the day is shortest", "equally spread over the planet", "most direct and the day is longest", "blocked by the Moon"]'::jsonb,2,'The Northern Hemisphere is tilted most toward the Sun.','original'),
('112.26.b.9.A',4,'Why is it not hotter in the whole world when Earth is closest to the Sun in January?','["the Moon blocks the Sun", "the Sun turns off", "Earth stops moving", "seasons are caused by tilt, not distance"]'::jsonb,3,'Earth''s tilt, not distance, drives seasons.','original'),
('112.26.b.9.B',2,'What mainly causes ocean tides?','["the gravity of the Moon and Sun", "ocean currents only", "wind only", "earthquakes"]'::jsonb,0,'Gravitational pull from the Moon and Sun creates tides.','original'),
('112.26.b.9.B',3,'How many high tides do most coasts have each day?','["none", "about two", "one", "four"]'::jsonb,1,'Most places have two high and two low tides a day.','original'),
('112.26.b.9.B',3,'Spring tides (very high and very low) occur when the Sun, Earth and Moon are...','["on opposite sides of the galaxy", "at right angles", "lined up", "far apart"]'::jsonb,2,'The combined pull is strongest at new and full moon.','original'),
('112.26.b.9.B',3,'Neap tides (small tidal range) occur when the Sun and Moon are...','["behind Earth", "very close to Earth", "lined up with Earth", "at right angles to Earth"]'::jsonb,3,'Their pulls partly cancel at first and third quarter moon.','original'),
('112.26.b.9.B',4,'At which Moon phase do spring tides occur?','["new moon and full moon", "only a crescent", "first and third quarter", "only a gibbous"]'::jsonb,0,'The Sun, Earth and Moon line up at new and full moon.','original'),
('112.26.b.9.B',4,'At which Moon phase do neap tides occur?','["new moon", "first quarter and third quarter", "full moon", "during eclipses only"]'::jsonb,1,'The pulls act at right angles.','original'),
('112.26.b.9.B',4,'Why does the tide go in and out about twice a day at a beach?','["winds turn on and off", "water evaporates twice a day", "Earth rotates under the tidal bulges", "the Moon moves around the beach"]'::jsonb,2,'Earth''s rotation moves coasts through the bulges.','original'),
('112.26.b.10.A',2,'Which Earth system includes all living things?','["geosphere", "atmosphere", "hydrosphere", "biosphere"]'::jsonb,3,'The biosphere is all life on Earth.','original'),
('112.26.b.10.A',2,'Which Earth system includes oceans, lakes and rivers?','["hydrosphere", "biosphere", "geosphere", "atmosphere"]'::jsonb,0,'Hydro means water.','original'),
('112.26.b.10.A',2,'Which Earth system is the layer of gases surrounding the planet?','["hydrosphere", "atmosphere", "biosphere", "geosphere"]'::jsonb,1,'The atmosphere is made of air.','original'),
('112.26.b.10.A',3,'Rocks, soil and mountains belong to which Earth system?','["atmosphere", "hydrosphere", "geosphere", "biosphere"]'::jsonb,2,'The geosphere is the solid Earth.','original'),
('112.26.b.10.A',3,'A volcano erupts and sends ash into the air. Which two systems interact?','["biosphere and hydrosphere only", "atmosphere and hydrosphere only", "no systems", "geosphere and atmosphere"]'::jsonb,3,'Rock material from the geosphere enters the air.','original'),
('112.26.b.10.A',4,'A tree absorbs water from soil and releases oxygen. Which systems are involved?','["biosphere, geosphere, hydrosphere and atmosphere", "atmosphere only", "geosphere only", "biosphere only"]'::jsonb,0,'All four interact.','original'),
('112.26.b.10.A',4,'Which is part of the hydrosphere?','["a cloud of oxygen", "glaciers", "a squirrel", "a canyon wall"]'::jsonb,1,'Frozen water is part of the hydrosphere.','original'),
('112.26.b.10.B',2,'Which layer of Earth is the thin, outermost layer?','["outer core", "mantle", "crust", "inner core"]'::jsonb,2,'The crust is the thin outer shell.','original'),
('112.26.b.10.B',3,'Which layer of Earth is the thickest?','["outer core", "crust", "inner core", "mantle"]'::jsonb,3,'The mantle makes up most of Earth''s volume.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_science_v1'
from (values
('112.26.b.10.B',3,'Which layer of Earth is made of solid iron and nickel because of the huge pressure?','["inner core", "mantle", "crust", "outer core"]'::jsonb,0,'Pressure keeps the inner core solid despite the heat.','original'),
('112.26.b.10.B',3,'Which layer of Earth is liquid metal?','["crust", "outer core", "mantle", "inner core"]'::jsonb,1,'The outer core is molten iron and nickel.','original'),
('112.26.b.10.B',4,'From the surface moving toward the center, which order of layers is correct?','["mantle, crust, inner core, outer core", "crust, outer core, mantle, inner core", "crust, mantle, outer core, inner core", "inner core, outer core, mantle, crust"]'::jsonb,2,'Layers get hotter and deeper going inward.','original'),
('112.26.b.10.B',4,'Which layer''s slow flowing movement helps move Earth''s tectonic plates?','["inner core", "crust", "atmosphere", "mantle"]'::jsonb,3,'Convection in the mantle drives plate movement.','original'),
('112.26.b.10.B',4,'Earth''s layers are sometimes modeled with a peach. What does the pit most likely represent?','["the core", "the atmosphere", "the mantle", "the crust"]'::jsonb,0,'The pit is the center, like the core.','original'),
('112.26.b.10.C',2,'Rock formed from cooled magma or lava is called...','["metamorphic rock", "igneous rock", "sedimentary rock", "mineral"]'::jsonb,1,'Igneous means formed from fire/melt.','original'),
('112.26.b.10.C',3,'Rock formed from layers of pressed sediment is called...','["igneous rock", "metamorphic rock", "sedimentary rock", "magma"]'::jsonb,2,'Layers of sediment get compacted and cemented.','original'),
('112.26.b.10.C',3,'Rock changed by heat and pressure without melting is called...','["lava", "sedimentary rock", "igneous rock", "metamorphic rock"]'::jsonb,3,'Metamorphic means changed in form.','original'),
('112.26.b.10.C',3,'Which rock is most likely to contain fossils?','["sedimentary rock", "obsidian", "igneous rock", "metamorphic rock made at great depth"]'::jsonb,0,'Fossils are preserved in sediment layers.','original'),
('112.26.b.10.C',4,'Limestone is heated and squeezed deep underground and becomes marble. Marble is a...','["igneous rock", "metamorphic rock", "sedimentary rock", "type of lava"]'::jsonb,1,'Heat and pressure changed it.','original'),
('112.26.b.10.C',4,'Which process turns rock into small pieces that can become sediment?','["compaction only", "melting and cooling", "weathering and erosion", "metamorphism"]'::jsonb,2,'Rocks break down and are moved.','original'),
('112.26.b.10.C',4,'Granite cools slowly from magma. Over time it is weathered into sand. The sand is then pressed into sandstone. Which sequence of rock types is correct?','["igneous, then metamorphic with no steps", "sedimentary, then igneous", "metamorphic, then igneous", "igneous, then sedimentary"]'::jsonb,3,'Weathering and compaction produce sedimentary rock.','original'),
('112.26.b.11.A',3,'Why is managing natural resources important?','["so people and ecosystems can keep having enough clean water, food and energy", "so resources are used up faster", "so fewer people have energy", "so pollution increases"]'::jsonb,0,'Careful use makes resources last.','original'),
('112.26.b.11.A',3,'Burning fossil fuels for energy can cause what environmental problem?','["more fresh water", "air pollution", "fewer clouds", "less carbon dioxide"]'::jsonb,1,'Burning fuels releases pollutants.','original'),
('112.26.b.11.A',3,'Poor management of water resources can lead to...','["greater food supply", "less disease", "water shortages and pollution", "more clean water"]'::jsonb,2,'Overuse and contamination hurt supplies.','original'),
('112.26.b.11.A',4,'How can reducing energy waste help with global poverty?','["it makes food rot", "it raises energy bills", "it removes all jobs", "lower energy costs leave more money for food, health care and education"]'::jsonb,3,'Savings can be used for basic needs.','original'),
('112.26.b.11.A',4,'Which is an effect of malnutrition that better food resource management may reduce?','["poor growth and health", "stronger immunity", "faster healing", "better school results"]'::jsonb,0,'Managing food supplies helps people get enough nutrients.','original'),
('112.26.b.11.A',4,'Which resource problem is caused by polluted air?','["more clean drinking water", "health problems like asthma", "more fertile soil", "cooler cities"]'::jsonb,1,'Air pollution harms lungs.','original'),
('112.26.b.11.A',4,'A city wastes much of its drinking water through leaky pipes. Which result is most likely?','["lower water bills for everyone", "more water in reservoirs", "less water available for people and higher costs", "cleaner rivers"]'::jsonb,2,'Wasted water reduces supply and raises costs.','original'),
('112.26.b.11.B',2,'Which action conserves energy at home?','["running empty dishwashers", "leaving the TV on all day", "opening the refrigerator often", "turning off lights when leaving a room"]'::jsonb,3,'Using less energy conserves it.','original'),
('112.26.b.11.B',3,'Which is a way to conserve water?','["taking shorter showers", "leaving the faucet running", "washing small loads of laundry", "watering lawns during rain"]'::jsonb,0,'Using less water saves it.','original'),
('112.26.b.11.B',3,'An LED light bulb uses much less electricity than an older bulb to produce the same light. This is an example of...','["more waste", "increased efficiency", "energy creation", "pollution"]'::jsonb,1,'Efficiency means getting the same result using less energy.','original'),
('112.26.b.11.B',3,'Planting cover crops helps protect which resource?','["oil", "air only", "soil", "natural gas"]'::jsonb,2,'Roots and plants hold soil and reduce erosion.','original'),
('112.26.b.11.B',4,'A power plant adds scrubbers that remove pollutants from smoke before it is released. This technology helps manage...','["soil minerals", "the Moon''s orbit", "tides", "air quality"]'::jsonb,3,'Scrubbers clean exhaust gases.','original'),
('112.26.b.11.B',4,'Which technology helps manage energy resources by making use of the Sun?','["solar panels", "diesel engines", "gas generators", "coal furnaces"]'::jsonb,0,'Solar panels convert sunlight to electricity.','original'),
('112.26.b.11.B',4,'Recycling aluminum cans saves energy because...','["it creates more ore", "making new cans from recycled metal takes far less energy than from raw ore", "it makes cans heavier", "it uses more water"]'::jsonb,1,'Recycling avoids energy-heavy mining and refining.','original'),
('112.26.b.12.A',3,'Two plants in the same patch compete for water and light. What happens if there is not enough of one resource?','["the resource increases", "competition stops", "some plants grow poorly or die", "all plants grow better"]'::jsonb,2,'Limited resources limit population size.','original'),
('112.26.b.12.A',3,'If a drought reduces water in a pond ecosystem, what will most likely happen to fish populations?','["they will stay exactly the same", "they will increase", "they will turn into plants", "they will decrease"]'::jsonb,3,'Less water means less habitat and food.','original'),
('112.26.b.12.A',4,'Rabbits in a field eat the available grass. What happens to the rabbit population if the grass supply drops sharply?','["the rabbit population will decrease", "the grass will grow faster", "nothing will change", "the rabbit population will increase"]'::jsonb,0,'Less food reduces how many rabbits can survive.','original'),
('112.26.b.12.A',4,'A new species of fish is added to a lake and eats the same food as native fish. What is likely to occur?','["more food for all", "competition for food", "the native fish eat less", "the lake dries up"]'::jsonb,1,'Sharing a limited resource creates competition.','original'),
('112.26.b.12.A',4,'Which change in an abiotic factor would most harm a coral reef ecosystem?','["more algae in a healthy balance", "more fish", "warmer ocean temperatures", "more sunlight in the right range"]'::jsonb,2,'Coral is sensitive to temperature.','original'),
('112.26.b.12.A',3,'In a desert ecosystem, cactuses, snakes and sand are all present. Which of these is an abiotic part of the ecosystem?','["the lizards", "the cactuses", "the snakes", "the sand"]'::jsonb,3,'Sand is non-living; cactuses and animals are living.','original'),
('112.26.b.12.A',4,'Coyotes and foxes in the same area both hunt rabbits. When rabbits become scarce, what is the most likely effect on the two predator populations?','["both populations face competition and may decline", "neither population is affected", "the rabbits stop being prey", "both populations grow quickly"]'::jsonb,0,'Fewer shared prey means more competition for food.','original'),
('112.26.b.12.B',2,'An owl hunts and eats mice. The owl is the...','["producer", "predator", "parasite", "prey"]'::jsonb,1,'Predators hunt and eat prey.','original'),
('112.26.b.12.B',3,'A tick feeds on a dog''s blood and harms the dog. This is...','["competition", "mutualism", "parasitism", "commensalism"]'::jsonb,2,'One organism benefits, the other is harmed.','original'),
('112.26.b.12.B',3,'Bees collect nectar from flowers and pollinate them. This is...','["commensalism", "parasitism", "predation", "mutualism"]'::jsonb,3,'Both organisms benefit.','original'),
('112.26.b.12.B',3,'A barnacle attaches to a whale. The barnacle gets a ride and food, and the whale is not affected. This is...','["commensalism", "mutualism", "predation", "parasitism"]'::jsonb,0,'One benefits and the other is neither helped nor harmed.','original'),
('112.26.b.12.B',4,'Two male deer fight for territory. This is an example of...','["mutualism", "competition", "commensalism", "parasitism"]'::jsonb,1,'Organisms compete for limited resources.','original'),
('112.26.b.12.B',4,'A clownfish lives among a sea anemone''s stinging tentacles, gaining protection, while it cleans the anemone and drives away fish that eat it. This is...','["competition", "parasitism", "mutualism", "commensalism"]'::jsonb,2,'Both species gain.','original'),
('112.26.b.12.B',4,'A mistletoe plant grows on a tree, taking water and nutrients from it and weakening it. The mistletoe is a...','["decomposer", "predator", "mutualist", "parasite"]'::jsonb,3,'It benefits at the tree''s expense.','original'),
('112.26.b.12.C',2,'A single living thing is called a(n)...','["organism", "community", "ecosystem", "population"]'::jsonb,0,'Organism is the smallest level of ecological organization.','original'),
('112.26.b.12.C',3,'All the deer living in one forest make up a...','["ecosystem", "population", "biosphere", "community"]'::jsonb,1,'A population is one species in one area.','original'),
('112.26.b.12.C',3,'All the populations of different species living together in an area make up a...','["organism", "population", "community", "cell"]'::jsonb,2,'A community includes all species there.','original'),
('112.26.b.12.C',3,'A community plus the non-living factors such as water, soil and sunlight is a(n)...','["population", "species", "organism", "ecosystem"]'::jsonb,3,'An ecosystem includes biotic and abiotic parts.','original'),
('112.26.b.12.C',4,'Which list is in order from smallest to largest?','["organism, population, community, ecosystem", "ecosystem, community, population, organism", "population, organism, ecosystem, community", "community, organism, population, ecosystem"]'::jsonb,0,'Each level contains the one before it.','original'),
('112.26.b.12.C',4,'A scientist counts all the frogs in a pond. What level of organization is she studying?','["organism", "population", "ecosystem", "community"]'::jsonb,1,'Frogs of one species form a population.','original'),
('112.26.b.12.C',4,'A scientist studies the frogs, fish, plants and insects in a pond. She is studying a...','["population", "organism", "community", "single species"]'::jsonb,2,'Several species living together form a community.','original'),
('112.26.b.13.A',2,'What is the basic unit of structure and function in living things?','["the tissue", "the atom", "the organ", "the cell"]'::jsonb,3,'Cells are the building blocks of life.','original'),
('112.26.b.13.A',3,'According to cell theory, new cells come from...','["pre-existing cells", "rocks", "nonliving matter", "air"]'::jsonb,0,'Cells divide to form new cells.','original'),
('112.26.b.13.A',3,'According to cell theory, all living things are made of...','["only atoms", "one or more cells", "only tissues", "only organs"]'::jsonb,1,'Even single-celled organisms are made of a cell.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_science_v1'
from (values
('112.26.b.13.A',3,'Which scientist is credited with first observing and naming cells in cork?','["Charles Darwin", "Isaac Newton", "Robert Hooke", "Gregor Mendel"]'::jsonb,2,'Hooke used a microscope in the 1600s.','original'),
('112.26.b.13.A',4,'Why was the invention of the microscope important for cell theory?','["it made cells larger permanently", "it created cells", "it removed the need for experiments", "it allowed scientists to see cells"]'::jsonb,3,'Cells are too small to see without magnification.','original'),
('112.26.b.13.A',4,'A student sees a single cell that moves, eats and reproduces. What does this suggest about it?','["it is a complete living organism", "it is just a part of a bigger animal", "it is a rock", "it is not alive"]'::jsonb,0,'A single cell can carry out all life processes.','original'),
('112.26.b.13.A',4,'Which statement is part of cell theory?','["cells are not found in plants", "cells are the basic unit of life", "cells can come from nonliving things", "cells are made by the nucleus only"]'::jsonb,1,'That is one of the three main ideas.','original'),
('112.26.b.13.B',3,'A cell without a nucleus, such as a bacterium, is called...','["autotrophic", "eukaryotic", "prokaryotic", "multicellular"]'::jsonb,2,'Prokaryotes lack a nucleus.','original'),
('112.26.b.13.B',3,'Plant and animal cells have a nucleus. They are classified as...','["viruses", "prokaryotic", "nonliving", "eukaryotic"]'::jsonb,3,'Eukaryotic cells have a membrane-bound nucleus.','original'),
('112.26.b.13.B',3,'A paramecium is made of a single cell. It is...','["unicellular", "nonliving", "autotrophic only", "multicellular"]'::jsonb,0,'Unicellular means one cell.','original'),
('112.26.b.13.B',3,'An organism that makes its own food from sunlight is called...','["parasitic only", "autotrophic", "unicellular only", "heterotrophic"]'::jsonb,1,'Autotrophs produce their own food.','original'),
('112.26.b.13.B',3,'An organism that must eat other organisms for food is called...','["a producer", "autotrophic", "heterotrophic", "prokaryotic"]'::jsonb,2,'Heterotrophs consume other organisms.','original'),
('112.26.b.13.B',4,'A tree is a multicellular, eukaryotic autotroph. Which organism has the same set of characteristics?','["a bacterium", "a cow", "a mushroom", "a sunflower"]'::jsonb,3,'A sunflower is a plant, so it is multicellular, eukaryotic and photosynthetic.','original'),
('112.26.b.13.B',4,'A mushroom has a nucleus, many cells, and absorbs food from decaying matter. It is...','["eukaryotic, multicellular and heterotrophic", "prokaryotic and unicellular", "unicellular and autotrophic", "prokaryotic and autotrophic"]'::jsonb,0,'Fungi are heterotrophic eukaryotes.','original'),
('112.26.b.13.C',2,'Why are differences among organisms in a population important?','["they remove predators", "some may survive better when the environment changes", "they stop reproduction", "they make all organisms identical"]'::jsonb,1,'Variation gives a chance that some will survive.','original'),
('112.26.b.13.C',3,'A beetle population has green and brown individuals. Birds see the green ones more easily against brown bark. Which are more likely to survive and reproduce?','["the green ones", "both equally", "the brown ones", "neither"]'::jsonb,2,'Camouflaged individuals avoid predators.','original'),
('112.26.b.13.C',3,'A drought makes plants with deeper roots more likely to survive. This is an example of...','["a change that cannot be inherited", "a harmful variation always", "no variation", "a helpful variation"]'::jsonb,3,'Deep roots reach water.','original'),
('112.26.b.13.C',4,'A disease kills most individuals in a population, but a few with a resistant trait survive. What is likely true of the next generation?','["more will have the resistant trait", "all will die", "none will have it", "fewer will have it"]'::jsonb,0,'Survivors pass the trait on.','original'),
('112.26.b.13.C',4,'Why can a population with little variation be at risk when a disease appears?','["it gains new traits at once", "if all are vulnerable, all could die", "it grows faster", "it becomes immune automatically"]'::jsonb,1,'Without variation, there may be no resistant individuals.','original'),
('112.26.b.13.C',4,'As an environment gets colder, which trait would be an advantage for a mammal?','["smaller body only", "less body fat", "thicker fur", "thin fur"]'::jsonb,2,'Insulation helps in the cold.','original'),
('112.26.b.13.C',4,'A trait that helps an organism survive in one environment may be a disadvantage in another. Which example fits this?','["all traits help everywhere", "green leaves help only in snow", "brown fur is always best", "white fur helps in snow but stands out in a forest"]'::jsonb,3,'A trait''s value depends on the environment.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
